begin;
do $$
declare w1 uuid:=gen_random_uuid();w2 uuid:=gen_random_uuid();job uuid:=gen_random_uuid();subject uuid:=gen_random_uuid();token1 uuid:=gen_random_uuid();token2 uuid:=gen_random_uuid();key text:=repeat('a',64);op uuid;op2 uuid;attempt uuid;state jsonb;result jsonb;stale boolean:=false;begin
 state:=jsonb_build_object('version',1,'paused',true,'drafts','[]'::jsonb,'accounts','[]'::jsonb,'jobs',jsonb_build_array(jsonb_build_object('id',job,'draftId',null,'subject',jsonb_build_object('kind','video','id',subject,'revision',1),'status','delivered','remoteId','fixture-456','history',jsonb_build_array(jsonb_build_object('at',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'status','delivered')))));
 insert into public.content_studio_workspaces(id,state) values(w1,state),(w2,state);
 if not public.studio_acquire_account_execution(w1,key,token1,job,'write') then raise exception 'First lease failed';end if;
 if public.studio_acquire_account_execution(w2,key,token2,job,'metrics') then raise exception 'Cross-workspace account overlap';end if;
 if not public.studio_mark_account_dispatch(w1,key,token1,job) then raise exception 'Dispatch intent failed';end if;
 if not public.studio_release_account_execution(w1,key,token1,false) then raise exception 'Release failed';end if;
 if public.studio_acquire_account_execution(w2,key,token2,job,'write') then raise exception 'Expired lease cleared unknown outcome';end if;
 if not public.studio_acquire_account_execution(w1,key,token2,job,'reconcile') then raise exception 'Original reconciliation blocked';end if;
 begin perform public.studio_commit_account_workspace(w1,key,token1,0,state);exception when others then stale:=true;end;
 if not stale then raise exception 'Stale owner persisted state';end if;
 result:=public.studio_commit_account_workspace(w1,key,token2,0,state);
 if jsonb_array_length(result)<>1 then raise exception 'Current owner commit failed';end if;
 if not public.studio_release_account_execution(w1,key,token2,true) then raise exception 'Resolution failed';end if;
 if not public.studio_acquire_account_execution(w2,key,token1,job,'metrics') then raise exception 'Resolved account remained blocked';end if;
 perform public.studio_release_account_execution(w2,key,token1,false);
 op:=public.studio_queue_metric_collection(w1,job,true);op2:=public.studio_queue_metric_collection(w1,job,true);
 if op<>op2 then raise exception 'Metric slot was duplicated';end if;
 select id into attempt from public.studio_metric_attempts where operation_id=op;
 update public.studio_operations set status='running',owner_token=token1,lease_until=now()+interval '90 seconds' where id=op;
 if public.studio_finish_metric_attempt(w1,attempt,op,token2,jsonb_build_object('views',0,'likes',null,'comments',null,'shares',null,'favorites',null,'clicks',null,'source','fixture','definition','fixture','adapterVersion','v1'),null,600) then raise exception 'Stale metric owner wrote observation';end if;
 if not public.studio_finish_metric_attempt(w1,attempt,op,token1,jsonb_build_object('views',0,'likes',null,'comments',null,'shares',null,'favorites',null,'clicks',null,'source','fixture','definition','fixture','adapterVersion','v1'),null,600) then raise exception 'Real zero was not saved';end if;
 if (select "values"->>'views' from public.studio_metric_observations where attempt_id=attempt)<>'0' then raise exception 'Zero value changed';end if;
 if public.studio_finish_metric_attempt(w1,attempt,op,token1,null,'METRICS_UNAVAILABLE',600) then raise exception 'Metric attempt was overwritten';end if;
 update public.studio_metric_polls set deadline=now()-interval '1 second' where workspace_id=w1 and job_id=job;
 stale:=false;begin perform public.studio_queue_metric_collection(w1,job,true);exception when others then stale:=true;end;
 if not stale then raise exception 'Expired window dispatched';end if;
 op2:=public.studio_queue_metric_collection(w2,job,true);
 update public.studio_operations set status='cancelled' where id=op2;
 if not exists(select 1 from public.studio_metric_attempts where operation_id=op2 and status='cancelled' and error='OPERATION_CANCELLED') then raise exception 'Cancelled metrics remained queued';end if;
 op2:=gen_random_uuid();attempt:=gen_random_uuid();
 insert into public.studio_operations(id,workspace_id,kind,input) values(op2,w2,'collect_metrics','{}'::jsonb);
 insert into public.studio_metric_attempts(id,workspace_id,job_id,slot,operation_id) values(attempt,w2,job,-1,op2);
 update public.studio_operations set status='failed',error='Restore interrupted active work; retry explicitly.' where id=op2;
 if not exists(select 1 from public.studio_metric_attempts where id=attempt and status='failed' and error='RESTORE_INTERRUPTED') then raise exception 'Restore terminal mapping differs';end if;
 raise notice 'Account fencing, unresolved barriers, cross-workspace serialization, independent-video metrics, slot deduplication, null/zero values and expiry passed.';
end $$;
rollback;
